from multiprocessing import Process, Value

def zaehle(z):
    for _ in range(10_000):
        with z.get_lock():
            z.value += 1

if __name__ == "__main__":
    z = Value("i", 0)   # Shared Memory
    ps = [Process(target=zaehle,
                  args=(z,)) for _ in range(4)]
    for p in ps:
        p.start()
    for p in ps:
        p.join()
    print(z.value)

# Ausgabe: 40000
# ohne Lock z. B. 11871 oder 23745
